// FAP §10 subflow design rule 2: normalize at the boundary.
// UIBUILDER's client lib emits the user's send-payload as the msg itself
// when it's an object (uibuilder.iife.js: makeMeAnObject). So FAP envelopes
// arrive at the top level of msg, and legacy {topic, payload} likewise.
// We accept both shapes (top-level + msg.data fallback for any legacy code
// that explicitly wrapped under .data) and classify into FAP / legacy / junk.
const src = (msg && typeof msg === 'object') ? msg : null;
const alt = src && typeof src.data === 'object' ? src.data : null;
for (const candidate of [src, alt]) {
    if (!candidate) continue;
    if (candidate.type === 'command' && typeof candidate.action === 'string' && typeof candidate.requestId === 'string') {
        msg._req = candidate;
        return msg;
    }
    if (typeof candidate.topic === 'string') {
        msg._legacy = { topic: candidate.topic, payload: candidate.payload, session: candidate.session, recordDetails: candidate.recordDetails };
        return msg;
    }
}
msg._malformed = true;
return msg;

// FAP §10 subflow design rule 3: separate validation from execution.
// FAP envelopes that fail validation get a structured error reply directly
// from here, bypassing the action switch. Legacy messages pass through
// untouched.
if (msg._malformed) {
    msg._result = { ok: false, errors: { action: 'malformed envelope' } };
    msg._req = { action: 'unknown', requestId: 'n/a' };
    return [null, msg];
}
return [msg, null];

// FAP §10: route to responsibility subflows by action namespace. Each
// case returns to one specific output corresponding to a link-out below.
// Outputs (in order): insight | trino | llm | ping | bootstrap |
// alerts | data-sources | provenance | integrations | schemas | admin |
// smart-city | data-products | analytics | unknown(legacy or 404)
//
// Phase 3 lands action handlers incrementally: link-outs that have no
// subscribing subflow yet still wire up cleanly, but the message will be
// dropped server-side until that feature's subflow lands. The transport.ts
// timeout handles client-side awareness.

function route(idx) {
    const out = new Array(15).fill(null);
    out[idx] = msg;
    return out;
}

// Legacy topic-based path — preserved during Phase 3 transition.
if (msg._legacy) {
    msg._socketId = msg._socketId || (msg._legacy.session && msg._legacy.session._socketId);
    switch (msg._legacy.topic) {
        case 'insight.request':
        case 'init':
            return route(0);
        case 'trino.query':
            return route(1);
        case 'llm.freeform':
            return route(2);
        default:
            node.warn('Unknown legacy topic: ' + msg._legacy.topic);
            msg._req = { action: 'legacy.' + msg._legacy.topic, requestId: 'n/a' };
            msg._result = { ok: false, errors: { action: 'unknown action' } };
            return route(14);
    }
}

const action = msg._req && msg._req.action;
if (!action) {
    msg._result = { ok: false, errors: { action: 'no action specified' } };
    return route(14);
}

if (action === 'insight.request' || action === 'init')   return route(0);
if (action === 'trino.query')                            return route(1);
if (action === 'llm.freeform')                           return route(2);
if (action === 'ping')                                   return route(3);
if (action === 'bootstrap.session')                      return route(4);
if (action.startsWith('alerts.'))                        return route(5);
if (action.startsWith('data-sources.'))                  return route(6);
if (action.startsWith('provenance.'))                    return route(7);
if (action.startsWith('integrations.'))                  return route(8);
if (action.startsWith('schemas.'))                       return route(9);
if (action.startsWith('admin.'))                         return route(10);

if (action.startsWith('smart-city.'))                    return route(11);
if (action.startsWith('data-products.'))                 return route(12);
if (action.startsWith('analytics.'))                     return route(13);

node.warn('Unknown action: ' + action);
msg._result = { ok: false, errors: { action: 'unknown action: ' + action } };
return route(14);

// FAP §10 subflow design rule 4: return explicit success or explicit failure.
// Build the §9 envelope on a fresh msg object so internal _* fields aren't
// part of the payload sent to the browser. UIBUILDER's sendToFe runs
// JSON.stringify(msg) eagerly inside log.trace(...) — if msg has circular
// refs (msg._req points back at the inbound msg), the stringify throws and
// the outbound emit is skipped. Strip _* fields here defensively.
const req = msg._req;
const result = msg._result;
const out = {
    _socketId: msg._socketId,
    topic: msg.topic
};
if (req && result) {
    out.payload = {
        type: 'result',
        ok: !!result.ok,
        action: req.action,
        sessionId: msg._sessionId,
        requestId: req.requestId,
        next: result.next,
        data: result.data,
        ui: result.ui,
        errors: result.errors || null
    };
} else if (msg.data && typeof msg.data === 'object' && typeof msg.data.topic === 'string') {
    out.payload = msg.data;
} else if (msg.payload !== undefined) {
    // event-style broadcast: payload already shaped, just forward.
    out.payload = msg.payload;
}
return out;

// Route to the requesting client by _socketId. Absent _socketId implies a
// broadcast (e.g. alerts.new push event) — UIBUILDER fans it out to all
// connected clients when _uib.clientId is unset.
if (msg._socketId) {
    msg._uib = { clientId: msg._socketId };
}
return msg;

const baseUrl = env.get('AI_INSIGHT_BASE_URL') || 'http://127.0.0.1:1880';

// Adapter: accept either FAP §9 (msg._req.payload) or legacy (msg.data.recordDetails).
// The dispatcher routes both shapes here; we normalise to a single internal
// reading of action/params so the middle of the flow stays unchanged.
let action, params;
if (msg._req && msg._req.payload) {
    action = msg._req.payload.action;
    params = msg._req.payload.params || {};
    msg._fap = true;
} else {
    action = msg.data && msg.data.recordDetails && msg.data.recordDetails.action;
    params = (msg.data && msg.data.recordDetails && msg.data.recordDetails.params) || {};
    msg._fap = false;
}

// Store original data for response routing
msg.originalData = msg.data;
msg.originalAction = action;

if (action === 'load-latest') {
    msg.url = baseUrl + '/api/v1/insights/latest';
    msg.method = 'GET';
    msg.payload = '';
} else if (action === 'energy-summary') {
    msg.url = baseUrl + '/api/v1/insights/energy-summary';
    msg.method = 'POST';
    msg.payload = {
        start_ts: params.start_ts,
        end_ts: params.end_ts,
        timezone: params.timezone || 'UTC',
        forecast_alpha: 0.6,
        trend_epsilon: 0.02,
        daily_overview_strategy: 'fallback_hourly',
        include_data: true
    };
} else if (action === 'anomaly-report') {
    msg.url = baseUrl + '/api/v1/insights/anomaly-report';
    msg.method = 'POST';
    msg.payload = {
        start_ts: params.start_ts,
        end_ts: params.end_ts,
        timezone: params.timezone || 'UTC',
        robust_z_threshold: 3.5,
        include_data: true
    };
} else if (action === 'city-status') {
    msg.url = baseUrl + '/api/v1/insights/city-status';
    msg.method = 'POST';
    msg.payload = {
        start_ts: params.start_ts,
        end_ts: params.end_ts,
        timezone: params.timezone || 'UTC',
        include_data: true
    };
} else {
    node.warn('Unknown action: ' + action);
    return null;
}

msg.headers = {
    'Content-Type': 'application/json',
    'x-agreement-id': 'agreement-ui',
    'x-asset-id': 'asset-ui',
    'x-user-roles': 'ai_insight_consumer'
};

return msg;

const statusCode = msg.statusCode;
const originalAction = msg.originalAction || (msg.originalData && msg.originalData.recordDetails && msg.originalData.recordDetails.action);

// Build the response payload once; both legacy msg.data.recordDetails and
// FAP msg._result.data point at it so either Vue caller sees the same shape.
let body;
if (statusCode >= 400 || !msg.payload) {
    body = {
        error: msg.payload?.detail || 'AI Insight Service returned error ' + statusCode,
        action: originalAction
    };
    msg._isError = true;
} else if (originalAction === 'load-latest') {
    body = { latest: msg.payload.latest || msg.payload };
} else {
    const response = msg.payload;
    body = {
        action: originalAction,
        insight: {
            type: response.insight_type,
            summary: response.summary,
            keyFindings: response.key_findings,
            recommendations: response.recommendations,
            metadata: response.metadata,
            data: response.data || null
        }
    };
}

// Legacy shape — preserved so existing useUiBuilderStore.requestInsight callers continue to resolve.
msg.data = {
    topic: msg._isError ? 'error' : (originalAction === 'load-latest' ? 'latest.response' : 'insight.response'),
    recordDetails: msg._isError ? { message: body.error, action: originalAction } : body
};
msg._socketId = msg.originalData?.session?._socketId;

// FAP §9 shape — set msg._result so the dispatcher's fn_build_response wraps it.
if (msg._fap) {
    msg._result = {
        ok: !msg._isError,
        data: body,
        errors: msg._isError ? { integration: { service: 'ai-insight-service', message: body.error } } : null
    };
}
return msg;

// Adapter: accept either FAP §9 (msg._req.payload) or legacy (msg.data.recordDetails).
// The dispatcher routes both shapes here; we normalise to a single internal
// reading so the rest of the flow stays unchanged.
let src;
if (msg._req && msg._req.payload) {
    src = msg._req.payload;
    msg._fap = true;
} else {
    src = (msg.data && msg.data.recordDetails) || {};
    msg._fap = false;
}

msg.originalLLMRequest = {
    userQuestion: src.userQuestion || src.query,
    selectedProvider: src.selectedProvider || 'openai',
    conversationContext: src.conversationContext || [],
    session: msg.data && msg.data.session,
    params: src.params || {}
};

// Build Trino context query
const params = msg.originalLLMRequest.params;
const explicitWindow = !!(params.start_ts && params.end_ts);
// Default window is anchored on MAX(hour) inside the SQL builder when
// no explicit window is given — wall-clock NOW would miss every gold
// row whenever the simulator's clock has drifted (60x acceleration).
const startTs = params.start_ts || '';
const endTs = params.end_ts || '';

// Keycloak token request
const tokenUrl = env.get('FACIS_KEYCLOAK_URL') || 'https://identity.facis.cloud/realms/facis/protocol/openid-connect/token';
const clientId = env.get('FACIS_OIDC_CLIENT_ID') || 'trino';
const clientSecret = env.get('FACIS_OIDC_CLIENT_SECRET') || '';
const username = env.get('FACIS_TRINO_USER') || 'admin';
const password = env.get('FACIS_TRINO_PASSWORD') || '';

msg.url = tokenUrl;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = `grant_type=password&client_id=${clientId}&client_secret=${clientSecret}&username=${username}&password=${password}&scope=openid`;

msg.trinoQuery = {
    startTs: startTs,
    endTs: endTs,
    explicitWindow: explicitWindow
};

return msg;

const token = msg.payload?.access_token;
if (!token) {
    node.warn('Failed to get Keycloak token, proceeding without Trino context');
    msg.trinoContext = { error: 'No Trino context available (auth failed)' };
    return [null, msg]; // Skip Trino, go to LLM directly
}

const trinoHost = env.get('FACIS_TRINO_HOST') || '212.132.83.150';
const trinoPort = env.get('FACIS_TRINO_PORT') || '8443';
const startTs = msg.trinoQuery?.startTs;
const endTs = msg.trinoQuery?.endTs;

// Query recent Gold Layer data for context
const explicitWindow = msg.trinoQuery?.explicitWindow === true;
const windowClause = explicitWindow
    ? `WHERE hour >= from_iso8601_timestamp('${startTs}') AND hour < from_iso8601_timestamp('${endTs}')`
    : `WHERE hour > (SELECT MAX(hour) FROM gold.net_grid_hourly) - INTERVAL '168' HOUR`;
const sql = `SELECT \n    hour,\n    avg_consumption_kw,\n    avg_generation_kw,\n    net_grid_kw,\n    estimated_hourly_cost_eur\nFROM gold.net_grid_hourly\n${windowClause}\nORDER BY hour DESC\nLIMIT 48`;

msg.url = `https://${trinoHost}:${trinoPort}/v1/statement`;
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Content-Type': 'text/plain',
    'X-Trino-User': env.get('FACIS_TRINO_USER') || 'admin',
    'X-Trino-Catalog': 'hive',
    'X-Trino-Schema': 'default'
};
msg.payload = sql;
msg.trinoToken = token;

return [msg, null];

// Extract data from Trino REST API response
const data = msg.payload;
let contextData = [];

try {
    if (data && data.data) {
        const columns = data.columns || [];
        const colNames = columns.map(c => c.name);
        contextData = data.data.map(row => {
            let obj = {};
            row.forEach((val, i) => {
                obj[colNames[i] || 'col_' + i] = val;
            });
            return obj;
        });
    }
} catch(e) {
    node.warn('Trino parse error: ' + e.message);
}

msg.trinoContext = {
    dataPoints: contextData.length,
    recentData: contextData.slice(0, 24),
    summary: contextData.length > 0 ? {
        latestHour: contextData[0]?.hour || 'unknown',
        avgNetGrid: contextData.length > 0 
            ? (contextData.reduce((s, r) => s + (parseFloat(r.net_grid_kw) || 0), 0) / contextData.length).toFixed(2) 
            : 'N/A',
        avgCost: contextData.length > 0 
            ? (contextData.reduce((s, r) => s + (parseFloat(r.estimated_hourly_cost_eur) || 0), 0) / contextData.length).toFixed(2) 
            : 'N/A'
    } : { note: 'No data available for the selected time range' }
};

return msg;

const req = msg.originalLLMRequest;
const context = msg.trinoContext || { note: 'No data context available' };

const systemPrompt = `You are the FACIS AI Insight Assistant for IoT and Smart City data analysis.\n\nYou have access to the following Gold Layer data context from the FACIS Lakehouse:\n${JSON.stringify(context, null, 2)}\n\nAvailable data sources:\n- Energy: hourly grid consumption/generation, daily costs, PV self-consumption\n- Smart City: streetlight zones, traffic patterns, city events, weather\n- Anomalies: statistical outlier candidates\n\nGuidelines:\n- Base your answers ONLY on the provided data context\n- If data is insufficient, say so explicitly\n- Provide specific numbers, timestamps, and metrics when available\n- Format responses with clear sections using Markdown\n- Keep responses concise but informative\n- Do not invent data points not present in the context`;

// Build messages array
const messages = [];

// Add conversation context for follow-ups
if (req.conversationContext && req.conversationContext.length > 0) {
    req.conversationContext.forEach(cm => {
        messages.push({ role: cm.role, content: cm.content });
    });
}

// Add current question
messages.push({ role: 'user', content: req.userQuestion });

msg.llmMessages = messages;
msg.llmSystemPrompt = systemPrompt;
msg.selectedProvider = req.selectedProvider || 'openai';

return msg;

const apiKey = env.get('FACIS_OPENAI_API_KEY') || '';
const model = env.get('FACIS_OPENAI_MODEL') || 'gpt-4.1-mini';

if (!apiKey) {
    msg.data = {
        topic: 'error',
        recordDetails: { message: 'OpenAI API key not configured' }
    };
    if (msg._fap) {
        msg._result = { ok: false, errors: { system: 'OpenAI API key not configured' } };
    }
    msg._socketId = msg.originalLLMRequest?.session?._socketId;
    return msg;
}

msg.url = 'https://api.openai.com/v1/chat/completions';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
};
msg.payload = {
    model: model,
    messages: [
        { role: 'system', content: msg.llmSystemPrompt },
        ...msg.llmMessages
    ],
    temperature: 0.3,
    max_tokens: 2048
};
msg.selectedModel = model;

return msg;

const apiKey = env.get('FACIS_ANTHROPIC_API_KEY') || '';
const model = env.get('FACIS_ANTHROPIC_MODEL') || 'claude-sonnet-4-20250514';

if (!apiKey) {
    msg.data = {
        topic: 'error',
        recordDetails: { message: 'Anthropic API key not configured' }
    };
    if (msg._fap) {
        msg._result = { ok: false, errors: { system: 'Anthropic API key not configured' } };
    }
    msg._socketId = msg.originalLLMRequest?.session?._socketId;
    return msg;
}

msg.url = 'https://api.anthropic.com/v1/messages';
msg.method = 'POST';
msg.headers = {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'Content-Type': 'application/json'
};
msg.payload = {
    model: model,
    max_tokens: 2048,
    system: msg.llmSystemPrompt,
    messages: msg.llmMessages
};
msg.selectedModel = model;
msg.selectedProvider = 'claude';

return msg;

const apiKey = env.get('FACIS_CUSTOM_LLM_KEY') || '';
const url = env.get('FACIS_CUSTOM_LLM_URL') || '';
const model = env.get('FACIS_CUSTOM_LLM_MODEL') || 'custom';

if (!url) {
    msg.data = {
        topic: 'error',
        recordDetails: { message: 'Custom LLM URL not configured' }
    };
    if (msg._fap) {
        msg._result = { ok: false, errors: { system: 'Custom LLM URL not configured' } };
    }
    msg._socketId = msg.originalLLMRequest?.session?._socketId;
    return msg;
}

msg.url = url;
msg.method = 'POST';
msg.headers = {
    'Content-Type': 'application/json'
};
if (apiKey) {
    msg.headers['Authorization'] = 'Bearer ' + apiKey;
}

// Use OpenAI-compatible format
msg.payload = {
    model: model,
    messages: [
        { role: 'system', content: msg.llmSystemPrompt },
        ...msg.llmMessages
    ],
    temperature: 0.3,
    max_tokens: 2048
};
msg.selectedModel = model;
msg.selectedProvider = 'custom';

return msg;

const provider = msg.selectedProvider || 'openai';
const statusCode = msg.statusCode;
let text = '';
let isError = false;
let errorMessage = '';

// Handle HTTP errors
if (statusCode >= 400 || !msg.payload) {
    isError = true;
    errorMessage = msg.payload?.error?.message || msg.payload?.detail || 'LLM request failed with status ' + statusCode;
} else {
    // Extract text based on provider response format
    try {
        if (provider === 'claude') {
            const content = msg.payload?.content;
            if (Array.isArray(content) && content.length > 0) {
                text = content.filter(c => c.type === 'text').map(c => c.text).join('\n');
            }
        } else {
            text = msg.payload?.choices?.[0]?.message?.content || '';
        }
    } catch(e) {
        text = 'Failed to parse LLM response: ' + e.message;
    }
    if (!text) text = 'The AI provider returned an empty response.';
}

const response = {
    text: isError ? '' : text,
    provider: provider,
    model: msg.selectedModel || 'unknown',
    timestamp: new Date().toISOString()
};

// Legacy shape — preserved so existing useUiBuilderStore.requestLlm callers continue to resolve.
msg.data = isError ? {
    topic: 'error',
    recordDetails: { message: 'LLM Error (' + provider + '): ' + errorMessage }
} : {
    topic: 'llm.response',
    recordDetails: { response }
};
msg._socketId = msg.originalLLMRequest?.session?._socketId;

// FAP §9 shape — set msg._result so the dispatcher's fn_build_response wraps it.
if (msg._fap) {
    msg._result = isError
        ? { ok: false, errors: { integration: { service: provider, message: errorMessage } } }
        : { ok: true, data: { response } };
}
return msg;

// Adapter: accept either FAP §9 (msg._req.payload) or legacy (msg.data.recordDetails).
// The dispatcher routes both shapes here. We synthesise an originalTrinoRequest
// shape that downstream nodes can read uniformly via msg.originalTrinoRequest.recordDetails.
if (msg._req && msg._req.payload) {
    msg._fap = true;
    msg.originalTrinoRequest = {
        recordDetails: msg._req.payload,
        session: msg.data && msg.data.session
    };
} else {
    msg._fap = false;
    msg.originalTrinoRequest = msg.data;
}

// Build Keycloak token request
const tokenUrl = env.get('FACIS_KEYCLOAK_URL') || 'https://identity.facis.cloud/realms/facis/protocol/openid-connect/token';
const clientId = env.get('FACIS_OIDC_CLIENT_ID') || 'trino';
const clientSecret = env.get('FACIS_OIDC_CLIENT_SECRET') || '';
const username = env.get('FACIS_TRINO_USER') || 'admin';
const password = env.get('FACIS_TRINO_PASSWORD') || '';

msg.url = tokenUrl;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = `grant_type=password&client_id=${clientId}&client_secret=${clientSecret}&username=${username}&password=${password}&scope=openid`;

return msg;

const token = msg.payload?.access_token;
if (!token) {
    msg.data = {
        topic: 'error',
        recordDetails: { message: 'Failed to authenticate with Keycloak for Trino access' }
    };
    if (msg._fap) {
        msg._result = { ok: false, errors: { integration: { service: 'keycloak', message: 'token grant failed' } } };
    }
    msg._socketId = msg.originalTrinoRequest?.session?._socketId;
    return msg;
}

const trinoHost = env.get('FACIS_TRINO_HOST') || '212.132.83.150';
const trinoPort = env.get('FACIS_TRINO_PORT') || '8443';
const queryType = msg.originalTrinoRequest?.recordDetails?.queryType || 'kpi-summary';
const params = msg.originalTrinoRequest?.recordDetails?.params || {};
// When start_ts/end_ts are not supplied, anchor on the LATEST hour in the
// target gold table (sim-clock-aware). Wall-clock defaults would miss
// every row when the simulator is running at >1x acceleration.
const explicitWindow = !!(params.start_ts && params.end_ts);
const startTs = params.start_ts || '';
const endTs = params.end_ts || '';

let sql = '';
switch(queryType) {
    case 'kpi-summary':
        sql = `SELECT \n            AVG(net_grid_kw) as avg_net_grid,\n            AVG(avg_generation_kw) as avg_pv_generation,\n            SUM(estimated_hourly_cost_eur) as total_cost\n        FROM gold.net_grid_hourly\n        WHERE ${explicitWindow ? `hour >= from_iso8601_timestamp('${startTs}') AND hour < from_iso8601_timestamp('${endTs}')` : `hour > (SELECT MAX(hour) FROM gold.net_grid_hourly) - INTERVAL '168' HOUR`}`;
        break;
    default:
        sql = msg.originalTrinoRequest?.recordDetails?.sql || 'SELECT 1';
}

msg.url = `https://${trinoHost}:${trinoPort}/v1/statement`;
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Content-Type': 'text/plain',
    'X-Trino-User': env.get('FACIS_TRINO_USER') || 'admin',
    'X-Trino-Catalog': 'hive',
    'X-Trino-Schema': 'default'
};
msg.payload = sql;
msg.trinoQueryType = queryType;

return msg;

const queryType = msg.trinoQueryType;
const data = msg.payload;

if (msg.statusCode >= 400 || !data) {
    msg.data = {
        topic: 'error',
        recordDetails: { message: 'Trino query failed' }
    };
    if (msg._fap) {
        msg._result = { ok: false, errors: { integration: { service: 'trino', message: 'query failed' } } };
    }
    msg._socketId = msg.originalTrinoRequest?.session?._socketId;
    return msg;
}

let result = {};
try {
    if (data.data && data.columns) {
        const cols = data.columns.map(c => c.name);
        const rows = data.data.map(row => {
            let obj = {};
            row.forEach((v, i) => { obj[cols[i]] = v; });
            return obj;
        });
        result = rows;
    }
} catch(e) {
    result = { error: e.message };
}

let body;
if (queryType === 'kpi-summary' && Array.isArray(result) && result.length > 0) {
    const row = result[0];
    body = {
        netGrid: row.avg_net_grid,
        pvGeneration: row.avg_pv_generation,
        dailyCost: row.total_cost
    };
    // Legacy kpi.update topic emission removed (2026-05-05). FAP §9 result via
    // msg._result below is the sole response path. Live KPI broadcasts are
    // produced by the scheduled 5-KPI-Broadcast tab as proper EventEnvelopes.
} else {
    body = { data: result };
    msg.data = { topic: 'trino.result', recordDetails: body };
}

msg._socketId = msg.originalTrinoRequest?.session?._socketId;

// FAP §9 shape — set msg._result so the dispatcher's fn_build_response wraps it.
if (msg._fap) {
    msg._result = { ok: true, data: body };
}
return msg;

// Cap on concurrent sessions — failsafe against missed disconnect events.
const MAX_SESSIONS = 1000;
const sessions = flow.get('sessions') || {};

const evt = msg && msg.uibuilderCtrl;
const sid = msg && msg._socketId;
if (!sid) return null;

if (evt === 'client connect') {
    if (Object.keys(sessions).length >= MAX_SESSIONS) {
        // Prune oldest 10% to make room.
        const entries = Object.entries(sessions).sort((a, b) => (a[1].connectedAt || 0) - (b[1].connectedAt || 0));
        const drop = entries.slice(0, Math.ceil(MAX_SESSIONS * 0.1));
        for (const [k] of drop) delete sessions[k];
        node.warn('sessions cap hit; pruned oldest ' + drop.length);
    }
    sessions[sid] = {
        connectedAt: Date.now(),
        conversationHistory: [],
        messageCount: 0,
        preferences: {}
    };
    flow.set('sessions', sessions);
    node.log('session connect: ' + sid + ' (n=' + Object.keys(sessions).length + ')');
} else if (evt === 'client disconnect') {
    if (sessions[sid]) {
        delete sessions[sid];
        flow.set('sessions', sessions);
        node.log('session disconnect: ' + sid);
    }
}
// 'ready' and other control events are no-ops here.
return null;

const action = msg._req && msg._req.action;
if (action !== 'bootstrap.session') {
    msg._result = { ok: false, errors: { action: 'bootstrap: unknown action: ' + action } };
    return msg;
}

const sid = msg._socketId;
const sessions = flow.get('sessions') || {};
const entry = sid && sessions[sid];

// Build initial view-model. Pulls latest known KPI snapshot, recent alerts,
// and conversation history. Phase 5 expands this with smart-city / data-products
// initial summaries. Returns a sessionId so the client persists it (FAP §11).
const alerts = (global.get('alerts') || []).slice(-20).reverse();
const engine = global.get('engine') || {};

msg._sessionId = sid;
msg._result = {
    ok: true,
    next: { step: 'dashboard' },
    data: {
        sessionId: sid,
        connectedAt: entry ? entry.connectedAt : Date.now(),
        engine_state: engine.state || 'unknown',
        recent_alerts: alerts,
        conversation_history: entry ? entry.conversationHistory : []
    }
};
return msg;

const sessions = flow.get('sessions') || {};
const rows = Object.entries(sessions).map(([socketId, s]) => ({
    socketId,
    connectedAt: s.connectedAt,
    messageCount: s.messageCount || 0
}));
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
msg.payload = { count: rows.length, sessions: rows };
return msg;

const sessions = flow.get('sessions') || {};
const cutoff = Date.now() - 60 * 60 * 1000;  // 1h
const before = Object.keys(sessions).length;
for (const [sid, s] of Object.entries(sessions)) {
    if (!s.connectedAt || s.connectedAt < cutoff) delete sessions[sid];
}
const after = Object.keys(sessions).length;
if (after < before) {
    flow.set('sessions', sessions);
    node.log('watchdog: pruned ' + (before - after) + ' stale sessions; ' + after + ' remain');
}
return null;

// Build the same Keycloak token request as tab-trino-query's prepare-trino-auth.
// This is the broadcast path — no msg._req or msg.data to forward; the result
// goes straight to a fan-out broadcast (no requestId).
//
// Env vars: prefer the cluster's AI_INSIGHT_TRINO__OIDC_* (the actual injected
// names per the helm chart), fall back to FACIS_* for older naming.
const formEncode = (pairs) => Object.entries(pairs)
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v))
    .join('&');

const tokenUrl = env.get('AI_INSIGHT_TRINO__OIDC_TOKEN_URL') || env.get('FACIS_KEYCLOAK_URL') || 'https://identity.facis.cloud/realms/facis/protocol/openid-connect/token';
const clientId = env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_ID') || env.get('FACIS_OIDC_CLIENT_ID') || 'OIDC';
const clientSecret = env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_SECRET') || env.get('FACIS_OIDC_CLIENT_SECRET') || '';
const username = env.get('AI_INSIGHT_TRINO__OIDC_USERNAME') || env.get('FACIS_TRINO_USER') || 'test';
const password = env.get('AI_INSIGHT_TRINO__OIDC_PASSWORD') || env.get('FACIS_TRINO_PASSWORD') || '';
const scope = env.get('AI_INSIGHT_TRINO__OIDC_SCOPE') || 'openid';

msg.url = tokenUrl;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = formEncode({
    grant_type: 'password',
    client_id: clientId,
    client_secret: clientSecret,
    username,
    password,
    scope,
});

return msg;

const token = msg.payload?.access_token;
if (!token) {
    node.warn('KPI broadcast: failed to fetch Keycloak token; skipping cycle');
    return null;
}

const trinoHost = env.get('AI_INSIGHT_TRINO__HOST') || env.get('FACIS_TRINO_HOST') || '212.132.83.150';
const trinoPort = env.get('AI_INSIGHT_TRINO__PORT') || env.get('FACIS_TRINO_PORT') || '8443';
const trinoUser = env.get('AI_INSIGHT_TRINO__USER') || env.get('FACIS_TRINO_USER') || 'test';
const trinoCatalog = env.get('AI_INSIGHT_TRINO__CATALOG') || 'fap-iotai-stackable';
const trinoSchema  = env.get('AI_INSIGHT_TRINO__TARGET_SCHEMA') || env.get('AI_INSIGHT_TRINO__SCHEMA') || 'gold';
const tableNetGrid = env.get('AI_INSIGHT_TRINO__TABLE_NET_GRID_HOURLY') || 'net_grid_hourly';

// Anchor the 24h window on the LATEST hour present in gold, not on wall-clock
// NOW. The simulator runs at 60x acceleration, so its emitted timestamps
// diverge from real time fast — a `WHERE hour >= NOW() - 24h` window misses
// every gold row whenever sim_time has drifted past the wall-clock NOW ± 24h
// band. MAX(hour) is what 'right now' means in this dataset; using it keeps
// the broadcast meaningful regardless of how long the sim has been running
// or how far ahead/behind sim time has wandered.
const sql = `SELECT \n    AVG(net_grid_kw) AS avg_net_grid,\n    AVG(avg_generation_kw) AS avg_pv_generation,\n    SUM(estimated_hourly_cost_eur) AS total_cost,\n    CAST((SELECT MAX(hour) FROM ${trinoSchema}.${tableNetGrid}) AS VARCHAR) AS data_as_of\nFROM ${trinoSchema}.${tableNetGrid}\nWHERE hour > (SELECT MAX(hour) FROM ${trinoSchema}.${tableNetGrid}) - INTERVAL '24' HOUR\n  AND hour <= (SELECT MAX(hour) FROM ${trinoSchema}.${tableNetGrid})`;

// Trino's /v1/statement returns a paginated chain (queued → planning → running
// → finished, follow nextUri at each step). Headers must persist across pages,
// so stash them under msg._trinoNextHeaders for the collect-pages loop below.
msg._trinoNextHeaders = {
    'Authorization': 'Bearer ' + token,
    'X-Trino-User': trinoUser,
    'X-Trino-Catalog': trinoCatalog,
    'X-Trino-Schema': trinoSchema
};
msg.url = `https://${trinoHost}:${trinoPort}/v1/statement`;
msg.method = 'POST';
msg.headers = Object.assign({ 'Content-Type': 'text/plain' }, msg._trinoNextHeaders);
msg.payload = sql;
msg._trinoRows = [];
msg._trinoColumns = [];

return msg;

// Trino /v1/statement is paginated: each response has nextUri until the
// query reaches FINISHED. Accumulate rows across pages, looping back to
// the http-request via output 1. When body.nextUri is absent, emit on
// output 2 with msg.trinoRows fully populated.
const status = Number(msg.statusCode || 0);
if (status >= 400) {
    node.warn('KPI broadcast: Trino HTTP ' + status + '; skipping cycle');
    return null;
}
const body = msg.payload || {};
if (Array.isArray(body.columns) && body.columns.length > 0 && (!Array.isArray(msg._trinoColumns) || msg._trinoColumns.length === 0)) {
    msg._trinoColumns = body.columns.map((c) => c.name);
}
const columns = msg._trinoColumns || [];
const rows = msg._trinoRows || [];
const data = Array.isArray(body.data) ? body.data : [];
for (const row of data) {
    if (!Array.isArray(row)) continue;
    const mapped = {};
    for (let i = 0; i < columns.length; i++) mapped[columns[i]] = row[i];
    rows.push(mapped);
}
msg._trinoRows = rows;

if (body.nextUri) {
    // Loop back to the http-request node with GET on the nextUri.
    msg.method = 'GET';
    msg.url = String(body.nextUri);
    msg.headers = Object.assign({}, msg._trinoNextHeaders || {});
    msg.payload = '';
    return [msg, null];
}

// Done — forward to build-event with rows.
msg.trinoRows = rows;
return [null, msg];

// At this point msg.trinoRows is the fully-collected result of the
// kpi-summary query (one row, three aggregates). Reshape into the
// FAP §9 EventEnvelope shape and broadcast.
const rows = Array.isArray(msg.trinoRows) ? msg.trinoRows : [];
if (rows.length === 0) {
    node.warn('KPI broadcast: Trino returned no rows; skipping cycle');
    return null;
}
const r = rows[0] || {};

// Emit a fresh msg containing only the payload — no msg._req / msg._result /
// msg._socketId leakage from the upstream HTTP request, so merge-session-send
// fans out to all clients (broadcast). updatedAt lets the SPA show recency
// ("Trino · Ns ago") so users can spot stale data when the schedule hiccups.
// dataAsOf is the latest `hour` present in the gold table at query time —
// distinct from updatedAt: it surfaces lakehouse-materializer staleness
// (silver → gold runs every 6h via cron). When dataAsOf trails sim_time by
// hours, the Trino aggregates are fresh-broadcast but stale-content; the SPA
// can render a banner instead of silently showing old numbers.
return {
    payload: {
        type: 'event',
        event: 'kpi.update',
        data: {
            netGrid:      r.avg_net_grid      ?? null,
            pvGeneration: r.avg_pv_generation ?? null,
            dailyCost:    r.total_cost        ?? null,
            updatedAt:    new Date().toISOString(),
            dataAsOf:     r.data_as_of        ?? null
        }
    }
};

// A single Trino/Keycloak hiccup must not stop the 60s schedule. Log and drop.
const err = msg.error || {};
node.warn('KPI broadcast cycle skipped: ' + (err.message || msg.payload || 'unknown error'));
return null;
